23: // MigrateDiskLayout creates symlinks from the current filenames (disk, iso) to
24: // the legacy filenames (diffdisk, basedisk) used by older Lima versions.
25: // The original files are left in place so older Lima versions can still use them.
26: func MigrateDiskLayout(instDir string) error {
27: 	diskPath := filepath.Join(instDir, filenames.Disk)
28: 	if osutil.FileExists(diskPath) {
29: 		return nil // already migrated or new instance
30: 	}
31: 
32: 	diffDiskPath := filepath.Join(instDir, filenames.DiffDiskLegacy)
33: 	if osutil.FileExists(diffDiskPath) {
34: 		logrus.Infof("Creating symlink %#q -> %#q", filenames.Disk, filenames.DiffDiskLegacy)
35: 		if err := os.Symlink(filenames.DiffDiskLegacy, diskPath); err != nil {
36: 			return fmt.Errorf("failed to symlink %#q to %#q: %w", filenames.Disk, filenames.DiffDiskLegacy, err)
37: 		}
38: 	}
39: 
40: 	baseDiskPath := filepath.Join(instDir, filenames.BaseDiskLegacy)
41: 	isoPath := filepath.Join(instDir, filenames.ISO)
42: 	if osutil.FileExists(baseDiskPath) && !osutil.FileExists(isoPath) {
43: 		isISO, err := iso9660util.IsISO9660(baseDiskPath)
44: 		if err != nil {
45: 			return err
46: 		}
47: 		if isISO {
48: 			logrus.Infof("Creating symlink %#q -> %#q", filenames.ISO, filenames.BaseDiskLegacy)
49: 			if err := os.Symlink(filenames.BaseDiskLegacy, isoPath); err != nil {
50: 				return fmt.Errorf("failed to symlink %#q to %#q: %w", filenames.ISO, filenames.BaseDiskLegacy, err)
51: 			}
52: 		}
53: 		// Non-ISO basedisk is a legacy qcow2 backing file; leave it for QEMU to resolve.
54: 	}
55: 
56: 	return nil
57: }
