59: // EnsureDisk creates the VM disk from the downloaded image.
60: // For ISO images, it renames the image to "iso" and creates an empty disk.
61: // For non-ISO images, it converts the image to "disk" and removes the original.
62: func EnsureDisk(ctx context.Context, instDir, diskSize string, diskImageFormat image.Type) error {
63: 	diskPath := filepath.Join(instDir, filenames.Disk)
64: 	if _, err := os.Stat(diskPath); err == nil || !errors.Is(err, os.ErrNotExist) {
65: 		return err
66: 	}
67: 
68: 	imagePath := filepath.Join(instDir, filenames.Image)
69: 	isISO, err := iso9660util.IsISO9660(imagePath)
70: 	if err != nil {
71: 		return err
72: 	}
73: 
74: 	diskSizeInBytes, _ := units.RAMInBytes(diskSize)
75: 	diskUtil := proxyimgutil.NewDiskUtil(ctx)
76: 
77: 	if isISO {
78: 		isoPath := filepath.Join(instDir, filenames.ISO)
79: 		if err := os.Rename(imagePath, isoPath); err != nil {
80: 			return err
81: 		}
82: 		f, err := os.Create(diskPath)
83: 		if err != nil {
84: 			_ = os.Rename(isoPath, imagePath)
85: 			return err
86: 		}
87: 		if err := f.Close(); err != nil {
88: 			os.Remove(diskPath)
89: 			_ = os.Rename(isoPath, imagePath)
90: 			return err
91: 		}
92: 		if err := diskUtil.Convert(ctx, diskImageFormat, diskPath, diskPath, &diskSizeInBytes, false); err != nil {
93: 			os.Remove(diskPath)
94: 			_ = os.Rename(isoPath, imagePath)
95: 			return fmt.Errorf("failed to create disk %#q: %w", diskPath, err)
96: 		}
97: 	} else {
98: 		if err := diskUtil.Convert(ctx, diskImageFormat, imagePath, diskPath, &diskSizeInBytes, false); err != nil {
99: 			return fmt.Errorf("failed to convert %#q to %#q: %w", imagePath, diskPath, err)
100: 		}
101: 		os.Remove(imagePath)
102: 	}
103: 	return nil
104: }
